# filename: sample_ams_text_probe.py
import re

samples = {
    "apples": "USDA standard for apples revised 2008 (example snippet)",
    "onions": "USDA dehydrated onions standard updated 2013 (example snippet)",
    "peas": "USDA frozen peas standard revised 2016 (example snippet)",
    "corn": "USDA sweet corn standard updated 2011 (example snippet)"
}

found_updates = {}
for k, text in samples.items():
    years = re.findall(r"20\d{2}|19\d{2}", text)
    found_updates[k] = max(int(y) for y in years) if years else None

print("Sample probe latest years:")
for k, y in found_updates.items():
    print(f"- {k}: {y}")
